<template>
  <!-- <div class="snowfall"></div>

  <div class="snowflake"></div> -->


  <div id="app" :class="typeof weather.main != 'undefined' && weather.main.temp > 10 ? 'warm' : ''">

    <main>
      <div class="search-box">
        <input type="text" class="search-bar" placeholder="Search...." v-model="query" @keypress="fetchWeather">
      </div>


      <div class="weather-wrap" v-if="weather.main">
        <div class="location-box">
          <div class="location">
            {{ weather.name }}, {{ weather.sys.country }}
          </div>
          <div class="date">
            {{ dateBuilder() }}
          </div>
        </div>

        <div class="weather-box">
          <div class="temp">
            {{ Math.round(weather.main.temp) }}°C
          </div>
          <div class="weather">
            {{ weather.weather[0].main }}
          </div>
        </div>
      </div>

      <floatCloude v-if="(typeof weather.main != 'undefined' && weather.weather[0].main == 'Clouds')" />

      <rainFall v-else-if="(typeof weather.main != 'undefined' && weather.weather[0].main == 'Rain')" :amount="300"
        :size="1" :speed="50" :wind="1" :opacity="0.01" :swing="1" :image="null" :zIndex="null" :resize="true"
        color="#5c5c8a" />

      <snowFall v-if="typeof weather.main != 'undefined' && weather.main.temp < -10" :amount="50" :size="5" :speed="1.5"
        :wind="1" :opacity="0.8" :swing="1" :image="null" :zIndex="null" :resize="true" color="#fff" />

    </main>

  </div>
</template>

<script>

import snowFall from './components/snowFall.vue';
import floatCloude from './components/floatingCloude.vue';
import rainFall from './components/rainFall.vue';

export default {
  name: 'App',

  components: {
    snowFall,
    floatCloude,
    rainFall,
  },
  data() {
    return {
      api_key: '375bfe50c27f01b3ae69a5cc7093cf80',
      url_base: "https://api.openweathermap.org/data/2.5/",
      query: "",
      weather: {}
    }
  },
  methods: {
    fetchWeather(e) {
      if (e.key === "Enter") {
        fetch(`${this.url_base}weather?q=${this.query}&units=metric&APPID=${this.api_key}`)
          .then(res => {
            return res.json();
          }).then(this.setResults);
      }
    },

    setResults(results) {
      this.weather = results;
    },

    dateBuilder() {
      let d = new Date();
      let months = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"];
      let days = ["Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"];

      let day = days[d.getDay()];
      let date = d.getDate();
      let month = months[d.getMonth()];
      let year = d.getFullYear();

      return `${day} ${date} ${month} ${year}`;
    }
  },
}
</script>

